const products = { mug: { priceCents: 1200, stock: 2 } };

function takeStock(products, sku, quantity) {
  const product = products[sku];
  if (!product || product.stock < quantity) return null;
  product.stock -= quantity;
  return { priceCents: product.priceCents };
}

const a = takeStock(products, "mug", 2);
const b = takeStock(products, "mug", 1);
const c = takeStock(products, "lamp", 1);
console.log(a?.priceCents, b, c);
