const stock = { tee: 5, mug: 0 };

function checkout(stock, items) {
  const next = { ...stock };
  for (const { sku, quantity } of items) {
    if ((next[sku] ?? 0) < quantity) throw new Error(`Not enough stock for ${sku}`);
    next[sku] -= quantity;
  }
  Object.assign(stock, next);
}

