  try {
    await transaction(async () => {
      if (!inStock) throw new Error("Not enough stock");
    });
  } catch {
    return "409";
  }
  await bus.publishEvent({ type: "order.placed", payload: { orderId: id } });
  return "201";
}

console.log(await checkout(1, true), await checkout(2, false));
